CREATE TABLE price_predictions(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`item_type` varchar(50)  NOT NULL COMMENT 'crop, livestock',`item_name` varchar(255)  NOT NULL COMMENT 'Crop type or livestock species',`variety` varchar(255)  NULL COMMENT 'Crop variety or livestock breed',`state` varchar(100)  NOT NULL,`district` varchar(100)  NULL,`prediction_date` timestamp  NOT NULL DEFAULT CURRENT_TIMESTAMP,`target_date` date  NOT NULL COMMENT 'Date for which price is predicted',`predicted_price` DECIMAL(10,2)  NOT NULL COMMENT 'Predicted price per unit',`confidence_score` DECIMAL(3,2)  NOT NULL COMMENT 'Confidence score 0-1',`price_range_min` DECIMAL(10,2)  NULL COMMENT 'Minimum expected price',`price_range_max` DECIMAL(10,2)  NULL COMMENT 'Maximum expected price',`trend` varchar(20)  NULL COMMENT 'up, down, stable',`demand_forecast` varchar(20)  NULL COMMENT 'high, medium, low',`supply_forecast` varchar(20)  NULL COMMENT 'high, medium, low',`season` varchar(50)  NULL COMMENT 'Kharif, Rabi, Zaid',`model_version` varchar(50)  NULL COMMENT 'Version of prediction model used',`factors` text  NULL COMMENT 'JSON of factors influencing prediction')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;